contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] memory tos, uint[] memory vals) public {
        require(tos.length > 0);
        require(tos.length == vals.length);
        uint beforeBalance = address(c).balance;
        address beforeFrom = c.from();
        bool reverted;
        bool ret;
        try c.transfer(tos, vals) returns (bool r) {
            ret = r;
            reverted = false;
        } catch {
            reverted = true;
        }
        if (beforeFrom != address(this)) {
            assert(reverted);
        } else {
            assert(reverted || (ret == true && address(c).balance == beforeBalance));
        }
    }

    receive() external payable {}
}

